#ifndef PSS_TESTS_FIXTURE_H
#define PSS_TESTS_FIXTURE_H

#include <stddef.h>
#include <stdint.h>

/*
 * Loads a file generated by tools/make_fixture.py from tests/fixtures/.
 * Returns a malloc'd buffer (free with fixture_free) or NULL.
 */
uint8_t *fixture_load(const char *name, size_t *len);

/* Loads any file by path; NULL if it does not exist. */
uint8_t *fixture_load_path(const char *path, size_t *len);

void fixture_free(uint8_t *buf);

#endif
